def resolve(path, cwd, links):
    # Validate inputs
    if not isinstance(cwd, str) or not cwd.startswith('/'):
        return None
    if not isinstance(path, str):
        return None
    if not isinstance(links, dict):
        return None

    # Convert relative path to absolute
    if not path.startswith('/'):
        if cwd == '/':
            current = '/' + path
        else:
            current = cwd + '/' + path
    else:
        current = path

    # Split into components
    components = current.split('/')

    # Process components
    resolved = []
    link_count = 0
    i = 0

    while i < len(components):
        comp = components[i]
        i += 1

        # Skip empty components and '.'
        if comp == '' or comp == '.':
            continue

        # Handle '..'
        if comp == '..':
            if resolved:
                resolved.pop()
            continue

        # Append component
        resolved.append(comp)

        # Build current path
        current_path = '/' + '/'.join(resolved)

        # Check if it's a symlink
        if current_path in links:
            link_count += 1
            if link_count > 8:
                return None

            target = links[current_path]

            # Convert target to absolute if needed
            if target.startswith('/'):
                # Absolute target: restart resolution
                resolved = []
                target_components = target.split('/')
            else:
                # Relative target: resolve relative to parent directory
                resolved.pop()  # Remove the symlink itself
                target_components = target.split('/')

            # Insert target components at current position
            components = target_components + components[i:]
            i = 0

    # Build final path
    if not resolved:
        return '/'

    return '/' + '/'.join(resolved)

